        {{-1.5629339e-06f,-2.96533108e-06f,6.66826963e-06f,0.0f},{4.1120839e-17f,-8.77142404e-18f,-6.6024544e-17f,0.0f}},
        {{-1.72902946e-06f,-5.12599945e-06f,1.25057995e-05f,0.0f},{-4.43094661e-16f,-2.4600894e-16f,2.33257971e-16f,0.0f}},
        {{8.8793372e-17f,-2.39101175e-16f,-2.21508155e-16f,0.0f},{-1.65883249e-24f,-1.40405882e-24f,2.92557586e-24f,0.0f}},
        {{-0.000309646275f,0.000138826668f,-0.00017144531f,0.0f},{1.45517912e-11f,3.26541028e-17f,-2.16103764e-17f,0.0f}},
        {{-1.5629339e-06f,-2.96533108e-06f,6.66826963e-06f,0.0f},{2.05604195e-17f,-4.38571202e-18f,-3.3012272e-17f,0.0f}},
        {{-1.72902946e-06f,-5.12599945e-06f,1.25057995e-05f,0.0f},{-2.2154733e-16f,-1.2300447e-16f,1.16628986e-16f,0.0f}},
        {{4.4396686e-17f,-1.19550588e-16f,-1.10754078e-16f,0.0f},{-8.29416244e-25f,-7.02029408e-25f,1.46278793e-24f,0.0f}},
        {{-0.000309646275f,0.000138826668f,-0.00017144531f,0.0f},{1.45518536e-11f,1.63270514e-17f,-1.08051882e-17f,0.0f}},
        {{-1.5629339e-06f,-2.96533108e-06f,6.66826963e-06f,0.0f},{1.02802098e-17f,-2.19285601e-18f,-1.6506136e-17f,0.0f}},
        {{-1.72902946e-06f,-5.12599945e-06f,1.25057995e-05f,0.0f},{-1.10773665e-16f,-6.15022351e-17f,5.83144928e-17f,0.0f}},
        {{2.2198343e-17f,-5.97752938e-17f,-5.53770388e-17f,0.0f},{-4.14708122e-25f,-3.51014704e-25f,7.31393966e-25f,0.0f}},
        {{-0.000309646275f,0.000138826668f,-0.00017144531f,0.0f},{1.45518849e-11f,8.1635257e-18f,-5.4025941e-18f,0.0f}},
        {{-1.5629339e-06f,-2.96533108e-06f,6.66826963e-06f,0.0f},{5.14010488e-18f,-1.09642801e-18f,-8.253068e-18f,0.0f}},
        {{-1.72902946e-06f,-5.12599945e-06f,1.25057995e-05f,0.0f},{-5.53868326e-17f,-3.07511176e-17f,2.91572464e-17f,0.0f}},
        {{1.10991715e-17f,-2.98876469e-17f,-2.76885194e-17f,0.0f},{-2.07354061e-25f,-1.75507352e-25f,3.65696983e-25f,0.0f}},
        {{-0.000309646275f,0.000138826668f,-0.00017144531f,0.0f},{1.45519005e-11f,4.08176285e-18f,-2.70129705e-18f,0.0f}},
        {{-1.5629339e-06f,-2.96533108e-06f,6.66826963e-06f,0.0f},{2.57005244e-18f,-5.48214003e-19f,-4.126534e-18f,0.0f}},
        {{-1.72902946e-06f,-5.12599945e-06f,1.25057995e-05f,0.0f},{-2.76934163e-17f,-1.53755588e-17f,1.45786232e-17f,0.0f}},
    };
    const std::uint32_t captured=positions.size()/4u;
    for (const float scale : {1.0e-6f,1.0f,1.0e6f}) {
        for (const float angle : {0.0f,1.0e-5f,0.01f,0.03f,0.0317f,0.3f,3.13159265f}) {
            positions.push_back({{0.0f,0.0f,1.0e-6f,0.0f},{}});
            positions.push_back({{}, {}});
            positions.push_back({{scale,0.0f,0.0f,0.0f},{}});
            positions.push_back({{scale*std::cos(angle),scale*std::sin(angle),0.0f,0.0f},{}});
        }
    }
    // Degenerate and invalid inputs retain their zero/NaN policies.
    positions.insert(positions.end(),4u,MRCompensatedPositionGPU{});
    const std::uint32_t invalidFixture=positions.size()/4u;
    const std::vector<MRCompensatedPositionGPU> invalidCopy(positions.begin(),positions.begin()+4u);
    positions.insert(positions.end(),invalidCopy.begin(),invalidCopy.end());
    positions[4u*invalidFixture+2u].low.x=std::numeric_limits<float>::quiet_NaN();
    const std::uint32_t count=positions.size()/4u;
    NMDeformableContactGPU contact{};
    contact.identity.z=NM_DEFORMABLE_CONTACT_VERTEX_TRIANGLE;
    contact.barrier.z=1.0e-5f;
    contact.mollifier.w=1.0f;
    const auto output=makeBuffer(device,std::vector<nm_float4>(count));
    const auto gradient=makeBuffer(device,std::vector<nm_float4>(count*2u));
    dispatch(device,queue,pipeline(device,library,
        "numi_matter_metal::nm_contact_check_compensated_barrier"),{
        {0u,makeBuffer(device,std::vector<NMDeformableContactGPU>(count,contact))},
        {1u,makeBuffer(device,positions)},{2u,output},{3u,gradient},
        {4u,makeBuffer(device,std::vector<std::uint32_t>{count})}},(count+31u)/32u,32u);
    const auto values=readBuffer<nm_float4>(output,count);
    for (std::uint32_t i=0u;i<captured;++i) {
        std::cout.precision(10);
        std::cout<<"compensated_contact_energy trial="<<i<<" energy="<<values[i].x
            <<" separation="<<values[i].y<<" mollifier="<<values[i].z
            <<" relative="<<(values[i].x/values[0].x-1.0f)<<"\n";
        require(values[i].w==1.0f && std::isfinite(values[i].x),
            "compensated barrier rejected finite captured contact");
    }
    require(std::abs(values[captured-1u].x/values.front().x-1.0f)<=1.0e-6f,
        "contact energy does not approach base under vanishing compensated trial");
    const auto gradients=readBuffer<nm_float4>(gradient,2u*count);
    using V=std::array<double,3u>;
    const auto sub=[](const V& a,const V& b) {return V{a[0]-b[0],a[1]-b[1],a[2]-b[2]};};
    const auto cross=[](const V& a,const V& b) {return V{
        a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};};
    const auto dot=[](const V& a,const V& b) {return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];};
    const auto point=[&](std::uint32_t i) {const auto p=positions[i];return V{
        double(p.high.x)+p.low.x,double(p.high.y)+p.low.y,double(p.high.z)+p.low.z};};
    for (std::uint32_t i=0u;i<invalidFixture;++i) {
        const V a=sub(point(4u*i+2u),point(4u*i+1u));
        const V b=sub(point(4u*i+3u),point(4u*i+1u));
        const V c=cross(a,b);const double aa=dot(a,a),bb=dot(b,b);
        const double sine=aa>0.0 && bb>0.0 ? dot(c,c)/(aa*bb):0.0;
        const double ratio=std::clamp(sine/1.0e-3,0.0,1.0);
        const double expected=ratio*(2.0-ratio);
        require(std::abs(values[i].z-expected)<=3.0e-6*std::max(expected,1.0e-20),
            "compensated angular mollifier differs from Float64 equation");
        V ga{},gb{};
        if (ratio>0.0 && ratio<1.0) {
            const V bc=cross(b,c),ca=cross(c,a);
            const double d=2.0*(1.0-ratio)/1.0e-3;
            for (unsigned j=0u;j<3u;++j) {
                ga[j]=d*(2.0*bc[j]/(aa*bb)-2.0*sine*a[j]/aa);
                gb[j]=d*(2.0*ca[j]/(aa*bb)-2.0*sine*b[j]/bb);
            }
        }
        for (unsigned j=0u;j<2u;++j) {
            const auto actual=gradients[2u*i+j];const V av{actual.x,actual.y,actual.z};
            const auto expectedGradient=j==0u?ga:gb;const auto delta=sub(av,expectedGradient);
            require(std::sqrt(dot(delta,delta))<=5.0e-6*std::max(1.0e-20,std::sqrt(dot(expectedGradient,expectedGradient))),
                "compensated angular gradient differs from Float64 analytic derivative");
        }
    }
    require(std::isnan(values[invalidFixture].z),"nonfinite compensated edge was admitted");
    require(std::isnan(gradients[2u*invalidFixture].x),"nonfinite edge lost invalid derivative");
    std::cout<<"compensated_mollifier Float64_value_and_gradient=true scales=3 degenerate_and_nonfinite=true result=PASS\n";
}


void checkReferenceSelfContactWidth(
    id<MTLDevice> device,id<MTLCommandQueue> queue,id<MTLLibrary> library) {
    constexpr unsigned count=97u,canaries=4u;
    std::vector<nm_float4> input;std::vector<NativeFloat2> limits;
    std::vector<double> gaps;
    for (unsigned i=0u;i<count;++i) {
        const float side=i%3u==0u ? 0.001f : i%3u==1u ? 0.01f : 0.1f;
        const float z=i%2u==0u ? 0.0f : 1.0f;
        const float dz=i%7u==0u ? 0.0001f : i%7u==1u ? 0.000001f :
            i%7u==2u ? 0.000004f : i%7u==3u ? 0.000009f :
            i%7u==4u ? 0.00002f : i%7u==5u ? 0.0f : 0.000000001f;
        const float x=i%4u==0u ? 2.0f : 0.0f;
        input.insert(input.end(),{
            {x,0,z,0},{x+side,0,z,0},{x,side,z,0},
            {x+0.1f*side,0.1f*side,z+dz,0},
            {x+0.9f*side,0.1f*side,z+dz,0},
            {x+0.1f*side,0.9f*side,z+dz,0}});
        limits.push_back({1e-5f,1e-9f});
        gaps.push_back(double(z+dz)-double(z));
    }
    // Crossing triangles have no reference separating-plane certificate.
    input[6u*(count-1u)+3u].z=-0.001f;
    input[6u*(count-1u)+4u].z=0.001f;
    input[6u*(count-1u)+5u].z=0.001f;
    gaps.back()=-1.0;
    std::vector<NativeFloat2> output(count+canaries,{123.0f,456.0f});
    auto ib=makeBuffer(device,input),lb=makeBuffer(device,limits),ob=makeBuffer(device,output);
    auto pipe=pipeline(device,library,"numi_matter_metal::nm_contact_check_reference_self_width");
    auto command=[queue commandBuffer];auto encoder=[command computeCommandEncoder];
    [encoder setComputePipelineState:pipe];[encoder setBuffer:ib offset:0 atIndex:0];
    [encoder setBuffer:lb offset:0 atIndex:1];[encoder setBuffer:ob offset:0 atIndex:2];
    [encoder setBytes:&count length:sizeof(count) atIndex:3];
    [encoder dispatchThreadgroups:MTLSizeMake(4,1,1) threadsPerThreadgroup:MTLSizeMake(32,1,1)];
    [encoder endEncoding];[command commit];[command waitUntilCompleted];
    require(command.status==MTLCommandBufferStatusCompleted,"reference width GPU command");
    output=readBuffer<NativeFloat2>(ob,count+canaries);
    unsigned adapted=0u,unchanged=0u;
    for (unsigned i=0u;i<count;++i) {
        const auto v=output[i];const float authored=limits[i].x,clearance=limits[i].y;
        require(std::isfinite(v.x)&&std::isfinite(v.y)&&v.x>0&&v.x<=authored,
            "finite bounded reference width");
        if (v.x<authored) {
            ++adapted;
            require(v.x>clearance &&
                    (v.x==2.0f*clearance || 2.0*double(v.x)<=gaps[i]),
                "adapted activation preserves clearance and reference scale");
            require(double(v.y)<=gaps[i],"separating plane is lower distance bound");
            // A separating plane may conservatively underestimate the
            // minimum distance; no near-equality is needed for this rule.
            require(v.y>0.0f,"adapted reference plane is certified");
        } else {
            ++unchanged;
            require(gaps[i]>=2.0*authored || v.y<=0.0f || gaps[i]<0.0,
                "reference width retained only for distant or uncertified pair");
        }
    }
    for (unsigned i=count;i<count+canaries;++i)
        require(output[i].x==123.0f&&output[i].y==456.0f,"reference width output canary");
    require(adapted>15u&&unchanged>15u,"reference width covers both policies");
    // Oblique parallel triangles: the exact Float32 source points have a
    // positive 8.6 nm gap, although forming closest points in absolute world
    // coordinates can round it to zero. Dyadic edges keep the Float64 oracle
    // exact before its final square root.
    const float ox=0.125f,oy=-1.75f,oz=0.25f,s=1.0f/4096.0f;
    const float dx=std::nextafter(ox,1.0f)-ox;
    const std::vector<nm_float4> oblique{
        {ox,oy,oz,0},{ox+s,oy+s,oz,0},{ox+s,oy,oz+s,0},
        {ox+s/8+dx,oy+s/8,oz,0},
        {ox+5*s/8+dx,oy+5*s/8,oz,0},
        {ox+5*s/8+dx,oy+s/8,oz+s/2,0}};
    const double exactGap=double(dx)/std::sqrt(3.0);
    auto obliqueInput=makeBuffer(device,oblique);
    auto obliqueLimit=makeBuffer(device,std::vector<NativeFloat2>{{1e-5f,1e-10f}});
    auto obliqueOutput=makeBuffer(device,std::vector<NativeFloat2>(2u,{123.0f,456.0f}));
    dispatch(device,queue,pipe,{{0u,obliqueInput},{1u,obliqueLimit},
        {2u,obliqueOutput},{3u,makeBuffer(device,std::vector<unsigned>{1u})}},1u,32u);
    const auto obliqueResult=readBuffer<NativeFloat2>(obliqueOutput,2u);
    std::cout<<"oblique_reference_gap native_width="<<obliqueResult[0].x
        <<" certified_gap="<<obliqueResult[0].y<<" Float64_gap="<<exactGap<<"\n";
    require(obliqueResult[0].x<1e-5f && obliqueResult[0].x>1e-10f &&
            2.0*double(obliqueResult[0].x)<=exactGap &&
            double(obliqueResult[0].y)<=exactGap,
        "world-space closest points lost the oblique Float32 reference gap");
    require(obliqueResult[1].x==123.0f&&obliqueResult[1].y==456.0f,
        "oblique reference-width output canary");
    // Captured Float32 Human faces with positive sub-clearance rest gaps.
    // Keep the existing collision clearance; avoid a 10um activation fallback.
    const std::vector<nm_float4> closeReference{
        {0x1.2bc61e0000000p-5f,-0x1.1bbfd00000000p-3f,0x1.9aea1c0000000p-4f,0},
        {0x1.307aec0000000p-5f,-0x1.17104a0000000p-3f,0x1.9635c20000000p-4f,0},
        {0x1.34214c0000000p-5f,-0x1.17261e0000000p-3f,0x1.a517f80000000p-4f,0},
        {0x1.2c6c720000000p-5f,-0x1.1b27be0000000p-3f,0x1.92ebbc0000000p-4f,0},
        {0x1.31c54e0000000p-5f,-0x1.195b620000000p-3f,0x1.a6bff40000000p-4f,0},
        {0x1.3421500000000p-5f,-0x1.17261c0000000p-3f,0x1.a518020000000p-4f,0},
        {0x1.3c29860000000p-5f,-0x1.9bf32e0000000p-4f,0x1.7b52f60000000p-3f,0},
        {0x1.3cad8c0000000p-5f,-0x1.9ac2760000000p-4f,0x1.7adaba0000000p-3f,0},
        {0x1.3cb9b80000000p-5f,-0x1.9a739a0000000p-4f,0x1.7b89640000000p-3f,0},
        {0x1.3c2af60000000p-5f,-0x1.9be09e0000000p-4f,0x1.7b89720000000p-3f,0},
        {0x1.3cb4ee0000000p-5f,-0x1.9ab16c0000000p-4f,0x1.7ad4020000000p-3f,0},
        {0x1.49b3f00000000p-5f,-0x1.e1e16e0000000p-4f,0x1.75d0e00000000p-3f,0},
    };
    auto closeInput=makeBuffer(device,closeReference);
    auto closeLimits=makeBuffer(device,std::vector<NativeFloat2>(2u,{1e-5f,1e-9f}));
    auto closeOutput=makeBuffer(device,std::vector<NativeFloat2>(3u,{123.0f,456.0f}));
    dispatch(device,queue,pipe,{{0u,closeInput},{1u,closeLimits},{2u,closeOutput},
        {3u,makeBuffer(device,std::vector<unsigned>{2u})}},1u,32u);
    const auto closeResults=readBuffer<NativeFloat2>(closeOutput,3u);
    for(unsigned i=0;i<2u;++i) {
        std::cout<<"close_reference_gap case="<<i<<" width="<<closeResults[i].x
            <<" certified_gap="<<closeResults[i].y<<" clearance="<<1e-9f<<"\n";
        require(closeResults[i].y>0.0f&&closeResults[i].y<2e-9f&&
            closeResults[i].x>=2e-9f&&closeResults[i].x<=2.000001e-9f,
            "positive sub-clearance source gap inflated its activation width");
    }
    require(closeResults[2].x==123.0f&&closeResults[2].y==456.0f,
        "close reference width output canary");
    // Width is derived solely from immutable reference positions: current
    // positions are deliberately absent from this interface.
    std::cout<<"reference_self_contact_width cases="<<count<<" adapted="<<adapted
        <<" unchanged="<<unchanged<<" exact_Float32_gap=true clearance_preserved=true canaries=4 PASS\n";
}

void checkFinalReferenceContactClearance(
    id<MTLDevice> device,id<MTLCommandQueue> queue,id<MTLLibrary> library) {
    std::vector<NMFEMNodeStateGPU> nodes;
    std::vector<NMDeformableContactGPU> contacts;
    std::vector<unsigned> expected;
    for(float origin:{0.0f,1.0f,128.0f})for(float gap:{1e-6f,1e-8f,5e-10f,0.0f,-1e-6f}) {
        const unsigned base=nodes.size();
        for(unsigned i=0;i<2u;++i) {
            NMFEMNodeStateGPU n{};
            n.restAndFixed={origin,origin,i==0u?gap:0.0f,0.0f};
            n.positionAndMass=n.restAndFixed;n.positionAndMass.w=1.0f;
            n.referenceDisplacementAndMode.w=1.0f;nodes.push_back(n);
        }
        NMDeformableContactGPU c{};
        c.nodes={base,base+1u,NM_INVALID_INDEX,NM_INVALID_INDEX};
        c.extraNodes={NM_INVALID_INDEX,NM_INVALID_INDEX,0u,0u};
        c.identity={0,0,NM_DEFORMABLE_CONTACT_POINT_POINT,NM_CONTACT_VALID};
        c.normalAndTOI={0,0,1,0};contacts.push_back(c);expected.push_back(gap>1e-9f?1u:0u);
    }
    {
        const unsigned base=nodes.size();
        { NMFEMNodeStateGPU n{};n.restAndFixed={1,1,0,0};
        n.referenceDisplacementAndMode={4.0165218373466871e-10f,5.2222053070760666e-11f,-1.0921926696383366e-09f,1.0f};
        n.referenceDisplacementLow={-6.0135865096482601e-18f,-1.6829221172962863e-18f,-1.5461051204910354e-17f,0.0f};nodes.push_back(n); }
        { NMFEMNodeStateGPU n{};n.restAndFixed={1,1,0,0};
        n.referenceDisplacementAndMode={2.1815469153807499e-05f,-0.00032371300039812922f,-0.00017340638441964984f,1.0f};
        n.referenceDisplacementLow={-4.7432191637927779e-13f,4.0822020243302948e-12f,-5.8510710382667086e-13f,0.0f};nodes.push_back(n); }
        { NMFEMNodeStateGPU n{};n.restAndFixed={1,1,0,0};
        n.referenceDisplacementAndMode={3.5018223570659757e-05f,0.0023981332778930664f,-0.00029880704823881388f,1.0f};
        n.referenceDisplacementLow={-2.4650640144570357e-13f,1.0708408465509578e-10f,1.4403141006258391e-11f,0.0f};nodes.push_back(n); }
        { NMFEMNodeStateGPU n{};n.restAndFixed={1,1,0,0};
        n.referenceDisplacementAndMode={2.7719636364054168e-06f,-0.00013905760715715587f,-1.7286332877120003e-05f,1.0f};
        n.referenceDisplacementLow={-8.8460278869790382e-14f,-6.5057937335966098e-12f,-6.6875286775305853e-13f,0.0f};nodes.push_back(n); }
        NMDeformableContactGPU c{};c.nodes={base,base+1u,base+2u,base+3u};
        c.extraNodes={NM_INVALID_INDEX,NM_INVALID_INDEX,0,0};
        c.identity={0,0,NM_DEFORMABLE_CONTACT_EDGE_EDGE,NM_CONTACT_VALID};
        c.normalAndTOI={-0.99241423606872559f,-0.00076351239113137126f,-0.12293742597103119f,0.0f};
        contacts.push_back(c);expected.push_back(1u);
    }
    auto nonreference=contacts.front();nonreference.nodes.x=nodes.size();
    auto n=nodes.front();n.referenceDisplacementAndMode.w=0.0f;nodes.push_back(n);
    contacts.push_back(nonreference);expected.push_back(0u);
    auto invalid=contacts.front();invalid.nodes.x=NM_INVALID_INDEX-1u;
    contacts.push_back(invalid);expected.push_back(0u);
    auto missing=contacts.front();missing.nodes.y=NM_INVALID_INDEX;
    contacts.push_back(missing);expected.push_back(0u);
    NMMatterDispatchGPU d{};d.environmentCount=1;d.femNodeCount=nodes.size();
    const unsigned count=contacts.size();
    auto out=makeBuffer(device,std::vector<unsigned>(count+4u,0xdeadbeefu));
    dispatch(device,queue,pipeline(device,library,
        "numi_matter_metal::nm_mixed_check_reference_contact_clearance"),{
        {0u,makeBuffer(device,std::vector<NMMatterDispatchGPU>{d})},
        {1u,makeBuffer(device,contacts)},{2u,makeBuffer(device,nodes)},{3u,out},
        {4u,makeBuffer(device,std::vector<unsigned>{count})},
        {5u,makeBuffer(device,std::vector<float>{1e-9f})}},1u,32u);
    const auto actual=readBuffer<unsigned>(out,count+4u);
    for(unsigned i=0;i<count;++i) {
        if(actual[i]!=expected[i])std::cerr<<"final_clearance_case="<<i<<" got="<<actual[i]<<" expected="<<expected[i]<<"\n";
        require(actual[i]==expected[i],"final reference contact plane/clearance certificate");
    }
    for(unsigned i=count;i<count+4u;++i)
        require(actual[i]==0xdeadbeefu,"final contact clearance canary");
    std::cout<<"final_contact_reference_clearance cases="<<count
        <<" world_translation_invariant=true hard_clearance=unchanged"
        <<" nonreference_rejected=true invalid_rejected=true canaries=4 PASS\n";
}

void checkFinalContactActivePrefix(
    id<MTLDevice> device,id<MTLCommandQueue> queue,id<MTLLibrary> library) {
    const auto certify=pipeline(device,library,"numi_matter_metal::nm_mixed_certify");
    const auto sourceCertify=pipeline(device,library,"numi_matter_metal::nm_mixed_certify",true);
    const auto tiled=pipeline(device,library,"numi_matter_metal::nm_mixed_certify_partials");
    const auto tiledSource=pipeline(device,library,"numi_matter_metal::nm_mixed_certify_partials",true);
    const auto finish=pipeline(device,library,"numi_matter_metal::nm_mixed_certify_finish");
    auto layoutFunction=[library newFunctionWithName:
        @"numi_matter_metal::nm_primal_contact_argument_layout"];
    auto arguments=[layoutFunction newArgumentEncoderWithBufferIndex:0u];
    require(arguments!=nil,"contact certificate argument encoder unavailable");
    for(unsigned mode=0u;mode<16u;++mode) {
        NMMatterDispatchGPU d{};d.environmentCount=1u;d.objectCount=1u;
        d.femNodeCount=mode==15u?4u:2u;d.deformableContactCapacity=8u;
        d.numericalLimits.x=1e-5f;d.numericalLimits.z=0.05f;
        NMMixedSolverGPU solver{};solver.residualTolerances={1e-5f,1e-5f,1e-5f,1e-5f};
        solver.contactAcceptance.x=1e-4f;
        NMFGMRESLayoutGPU layout{};NMFGMRESStateGPU state{};state.diagnostics.y=1.0f;
        NMContinuumObjectGPU object{};object.representation=NM_REPRESENTATION_FEM;
        object.flags=NM_OBJECT_ACTIVE;object.stateCount=d.femNodeCount;
        const float gap=mode>=9u?(mode==12u?4e-10f:mode==14u?-6e-10f:6e-10f):mode==5u?7e-10f:mode==8u?-5e-10f:
            (mode==1u||mode>=4u)?5e-10f:1e-8f;
        const float initialGap=mode>=9u?8e-10f:mode==6u?7e-10f:mode==7u?0.0f:
            mode>=4u?5e-10f:1e-8f;
        std::vector<NMFEMNodeStateGPU> nodes(d.femNodeCount);
        for(unsigned i=0u;i<2u;++i) {
            nodes[i].restAndFixed={1.0f,1.0f,0.0f,0.0f};
            nodes[i].positionAndMass={1.0f,1.0f,0.0f,1.0f};
            nodes[i].referenceDisplacementAndMode={0.0f,0.0f,i==0u?gap:0.0f,1.0f};
        }
        auto initialNodes=nodes;initialNodes[0].referenceDisplacementAndMode.z=initialGap;
        if(mode>=9u&&mode<15u) {
            nodes[0].restAndFixed.z=mode==11u?0.0f:7e-10f;
            initialNodes[0].restAndFixed.z=nodes[0].restAndFixed.z;
            nodes[0].referenceDisplacementAndMode.z=gap-nodes[0].restAndFixed.z;
            initialNodes[0].referenceDisplacementAndMode.z=initialGap-nodes[0].restAndFixed.z;
            if(mode==13u)nodes[0].referenceDisplacementAndMode.w=0.0f;
        }
        std::vector<NMDeformableContactGPU> contacts(8u);
        for(unsigned slot:{1u,5u,6u}) {
            auto& c=contacts[slot];c.nodes={0u,1u,NM_INVALID_INDEX,NM_INVALID_INDEX};
            c.extraNodes={NM_INVALID_INDEX,NM_INVALID_INDEX,0u,0u};
            c.identity={0u,0u,NM_DEFORMABLE_CONTACT_POINT_POINT,NM_CONTACT_VALID};
            c.normalAndTOI={0,0,1,0};c.pointAndSeparation={1,1,0,std::abs(gap)};
        }
        if(mode==15u) {
            const float rest[4][3]={{0.0f,0.0f,0.0f},{3.7997961044311523e-06f,9.775161743164062e-06f,-1.2621283531188965e-05f},{-1.2218952178955078e-06f,-3.2186508178710938e-06f,4.0084123611450195e-06f},{0.00021311640739440918f,0.003581523895263672f,0.0015106499195098877f}};
            const float currentHigh[4][3]={{6.340850622343908e-10f,4.231919703556741e-09f,-1.7631238691251383e-08f},{3.800809508902603e-06f,9.77997751760995e-06f,-1.263965623365948e-05f},{-1.220938315782405e-06f,-3.21404741043807e-06f,3.9904166442283895e-06f},{0.0002131059009116143f,0.003581523895263672f,0.001510553527623415f}},currentLow[4][3]={{1.7238836049215447e-17f,7.654939823313552e-17f,-6.242760934997466e-16f},{5.84714094091672e-14f,-3.957887349022998e-13f,2.8064440420021153e-13f},{5.040827577942365e-14f,-2.7110602377942127e-14f,1.3339520731504156e-13f},{-3.9828928458281176e-13f,-7.671274032672315e-11f,4.4868071064074755e-11f}};
            const float initialHigh[4][3]={{5.622190490939261e-10f,3.939301329580758e-09f,-1.5472584991016447e-08f},{3.8007144667062676e-06f,9.779606443771627e-06f,-1.2637385225389153e-05f},{-1.2210247177790734e-06f,-3.214370508430875e-06f,3.992610800196417e-06f},{0.00021310834563337266f,0.0035815236624330282f,0.0015105721540749073f}},initialLow[4][3]={{8.052223587302563e-18f,1.1238876512978385e-16f,-1.5226330434292307e-16f},{-4.2955985041790226e-14f,2.0969620286612027e-14f,-3.195142989163152e-13f},{1.1771963104019543e-14f,5.91055186022725e-14f,-1.0433345946090147e-13f},{-3.142800906671961e-12f,-3.963985042987339e-11f,5.7958405436098204e-11f}};
            for(unsigned i=0u;i<4u;++i) {
                nodes[i].restAndFixed={rest[i][0],rest[i][1],rest[i][2],0.0f};
                initialNodes[i]=nodes[i];
                for(unsigned j=0u;j<3u;++j) {
                    const double c=double(currentHigh[i][j])+currentLow[i][j]-rest[i][j];
                    const double a=double(initialHigh[i][j])+initialLow[i][j]-rest[i][j];
                    reinterpret_cast<float*>(&nodes[i].referenceDisplacementAndMode)[j]=float(c);
                    reinterpret_cast<float*>(&nodes[i].referenceDisplacementLow)[j]=float(c-double(float(c)));
                    reinterpret_cast<float*>(&initialNodes[i].referenceDisplacementAndMode)[j]=float(a);
                    reinterpret_cast<float*>(&initialNodes[i].referenceDisplacementLow)[j]=float(a-double(float(a)));
                }
                nodes[i].referenceDisplacementAndMode.w=initialNodes[i].referenceDisplacementAndMode.w=1.0f;
            }
            for(unsigned slot:{1u,5u}) {
                auto& c=contacts[slot];c.nodes={0u,1u,2u,3u};
                c.identity.z=NM_DEFORMABLE_CONTACT_VERTEX_TRIANGLE;
                c.normalAndTOI={-0.9728127121925354f,0.13672375679016113f,-0.18692810833454132f,0.0f};
                c.pointAndSeparation.w=8.71025363e-10f;
            }
        }
        contacts[6].pointAndSeparation.w=std::numeric_limits<float>::quiet_NaN();
        auto zero=makeBuffer(device,std::vector<unsigned>(64u,0u));
        auto count=makeBuffer(device,std::vector<unsigned>{mode==3u?0u:2u});
        auto contactBuffer=makeBuffer(device,contacts);
        id<MTLBuffer> args=[device newBufferWithLength:arguments.encodedLength
            options:MTLResourceStorageModeShared];
        [arguments setArgumentBuffer:args offset:0u];
        for(NSUInteger i=0u;i<20u;++i)[arguments setBuffer:zero offset:0u atIndex:i];
        [arguments setBuffer:contactBuffer offset:0u atIndex:7u];
        [arguments setBuffer:count offset:0u atIndex:14u];
        auto nodeBuffer=makeBuffer(device,nodes);
        auto fields=makeBuffer(device,std::vector<NMFEMFieldStateGPU>(d.femNodeCount));
        auto residual=makeBuffer(device,std::vector<nm_float4>(2u*d.femNodeCount));
        std::vector<NMSolverCertificateGPU> certificates(2u);
        std::memset(&certificates[1],0xa5,sizeof(certificates[1]));
        std::vector<NMMatterStatusGPU> statuses(2u);
        std::memset(&statuses[1],0xa5,sizeof(statuses[1]));
        auto output=makeBuffer(device,certificates);auto status=makeBuffer(device,statuses);
        auto dummy=makeBuffer(device,std::vector<unsigned>(1024u,0u));
        std::vector<std::pair<NSUInteger,id<MTLBuffer>>> bindings{
            {0u,makeBuffer(device,std::vector<NMMatterDispatchGPU>{d})},
            {1u,makeBuffer(device,std::vector<NMMixedSolverGPU>{solver})},
            {2u,makeBuffer(device,std::vector<NMContinuumObjectGPU>{object})},
            {3u,makeBuffer(device,initialNodes)},{4u,nodeBuffer},{5u,fields},{6u,fields},{7u,dummy},
            {8u,output},{9u,status},{10u,residual},
            {11u,makeBuffer(device,std::vector<NMFGMRESStateGPU>{state})},
            {12u,residual},{13u,dummy},{14u,residual},{15u,dummy},{16u,zero},{17u,zero},
            {18u,dummy},{19u,args},{20u,dummy},{21u,dummy},
            {22u,makeBuffer(device,std::vector<unsigned>{mode==2u?9u:5u,1u})},
            {30u,makeBuffer(device,std::vector<NMFGMRESLayoutGPU>{layout})}};
        auto command=[queue commandBuffer];auto encoder=[command computeCommandEncoder];
        [encoder setComputePipelineState:mode>=10u?sourceCertify:certify];
        for(const auto& [index,buffer]:bindings)[encoder setBuffer:buffer offset:0u atIndex:index];
        for(auto buffer:{zero,count,contactBuffer})[encoder useResource:buffer usage:MTLResourceUsageRead];
        [encoder dispatchThreadgroups:MTLSizeMake(1,1,1) threadsPerThreadgroup:MTLSizeMake(32,1,1)];
        [encoder endEncoding];[command commit];[command waitUntilCompleted];
        require(command.status==MTLCommandBufferStatusCompleted,"contact certificate GPU command failed");
        const auto got=readBuffer<NMMatterStatusGPU>(status,2u);
        const auto cert=readBuffer<NMSolverCertificateGPU>(output,2u);
        // Replay the identical GPU inputs through distributed measurement and
        // the shared acceptance authority, preserving output canaries.
        std::memcpy(output.contents,certificates.data(),certificates.size()*sizeof(certificates[0]));
        std::memcpy(status.contents,statuses.data(),statuses.size()*sizeof(statuses[0]));
        auto partials=makeBuffer(device,std::vector<nm_float4>(128u*7u+4u,
            nm_float4{123.0f,124.0f,125.0f,126.0f}));
        auto distributed=[queue commandBuffer];
        auto e=[distributed computeCommandEncoder];
        [e setComputePipelineState:mode>=10u?tiledSource:tiled];
        for(const auto& [index,buffer]:bindings)[e setBuffer:buffer offset:0u atIndex:index];
        [e setBuffer:partials offset:0u atIndex:23u];
        for(auto buffer:{zero,count,contactBuffer})[e useResource:buffer usage:MTLResourceUsageRead];
        [e dispatchThreadgroups:MTLSizeMake(128u,1u,1u)
            threadsPerThreadgroup:MTLSizeMake(32u,1u,1u)];
        [e memoryBarrierWithScope:MTLBarrierScopeBuffers];
        [e setComputePipelineState:finish];
        [e dispatchThreadgroups:MTLSizeMake(1u,1u,1u)
            threadsPerThreadgroup:MTLSizeMake(32u,1u,1u)];
        [e endEncoding];[distributed commit];[distributed waitUntilCompleted];
        require(distributed.status==MTLCommandBufferStatusCompleted,
            "tiled mixed certificate GPU command failed");
        const auto tiledStatus=readBuffer<NMMatterStatusGPU>(status,2u);
        const auto tiledCert=readBuffer<NMSolverCertificateGPU>(output,2u);
        require(std::memcmp(got.data(),tiledStatus.data(),2u*sizeof(got[0]))==0,
            "tiled contact certificate status/witness and canary parity");
        require(std::memcmp(cert.data(),tiledCert.data(),2u*sizeof(cert[0]))==0,
            "tiled contact certificate value and canary parity");
        const auto tail=readBuffer<nm_float4>(partials,128u*7u+4u);
        for(unsigned i=128u*7u;i<tail.size();++i)
            require(tail[i].x==123.0f&&tail[i].y==124.0f&&
                    tail[i].z==125.0f&&tail[i].w==126.0f,
                "tiled certificate partial canary");
        const bool expectedFailure=mode==1u||mode==2u||(mode>=6u&&mode<=9u)||
            (mode>=11u&&mode<=14u);
        if(got[0].code!=(expectedFailure?NM_STATUS_NONLINEAR_SOLVER_FAILURE:0u))
            std::cerr<<"final_contact_active_case="<<mode<<" got="<<got[0].code<<"\n";
        require(got[0].code==(expectedFailure?NM_STATUS_NONLINEAR_SOLVER_FAILURE:0u),
            "final certificate active prefix/clearance result");
        if(mode==1u||(mode>=6u&&mode<=9u)||(mode>=11u&&mode<=14u))require(got[0].failingIndex==1u&&got[0].diagnostics.x==std::abs(gap),
            "contact certificate lost deterministic minimum-slot witness");
        require(std::memcmp(&got[1],&statuses[1],sizeof(got[1]))==0,
            "contact certificate status canary");
        require(std::memcmp(&cert[1],&certificates[1],sizeof(cert[1]))==0,
            "contact certificate output canary");
        require(cert[0].nonlinear.x==0.0f&&cert[0].validity.x==1.0f,
            "contact certificate changed residual or element acceptance");
    }
    std::cout<<"final_contact_active_prefix=true sparse_order=true poisoned_padding_ignored=true"
        " empty=true invalid_index_rejected=true hard_clearance_preserved=true"
        " deterministic_witness=true canaries=2 cases=16 initially_close_nonclosing=true default_clearance_preserved=true source_margin_pipeline=true captured_full_Human_case=true source_overlap_rejected=true below_source_margin_rejected=true PASS\n";
}


void checkTiledMixedCertificateDomains(
    id<MTLDevice> device,id<MTLCommandQueue> queue,id<MTLLibrary> library) {
    const auto legacy=pipeline(device,library,"numi_matter_metal::nm_mixed_certify");
    const auto tiled=pipeline(device,library,"numi_matter_metal::nm_mixed_certify_partials");
    const auto finish=pipeline(device,library,"numi_matter_metal::nm_mixed_certify_finish");
    auto f=[library newFunctionWithName:@"numi_matter_metal::nm_primal_contact_argument_layout"];
    auto ae=[f newArgumentEncoderWithBufferIndex:0u];
    require(ae!=nil,"mixed tiled domain argument encoder");
    for(unsigned fault=0;fault<5u;++fault) {
        NMMatterDispatchGPU d{};d.environmentCount=2;d.objectCount=3;
        d.femNodeCount=519;d.tetrahedronCount=2;d.mixedMaterialCount=1;
        d.deformableContactCapacity=520;d.numericalLimits={1e-5f,0,0.05f,0};
        NMMixedSolverGPU solver{};solver.regularization.x=1e-6f;
        solver.residualTolerances={1e-3f,1e-3f,1e-3f,1e-3f};
        solver.contactAcceptance.x=1e-4f;
        NMFGMRESLayoutGPU layout{};
        std::vector<NMContinuumObjectGPU> objects(3);
        for(unsigned o=0;o<2u;++o) {
            objects[o].representation=NM_REPRESENTATION_FEM;
            objects[o].flags=NM_OBJECT_ACTIVE|NM_OBJECT_MIXED_FEM|NM_OBJECT_MULTIPHYSICS;
            objects[o].stateOffset=o==0?0:4;objects[o].stateCount=o==0?4:515;
            objects[o].elementOffset=o;objects[o].elementCount=1;
        }
        std::vector<NMFEMNodeStateGPU> nodes(2*d.femNodeCount);
        std::vector<NMFEMFieldStateGPU> fields(nodes.size());
        std::vector<nm_float4> residual(2*nodes.size()),fieldResidual(nodes.size()),
            correction(residual.size());
        for(unsigned env=0;env<2u;++env)for(unsigned i=0;i<d.femNodeCount;++i) {
            const unsigned g=env*d.femNodeCount+i;
            const unsigned corner=i%4u;
            const float x=corner==1?1.0f:0.0f,y=corner==2?1.0f:0.0f,z=corner==3?1.0f:0.0f;
            nodes[g].positionAndMass={x,y,z,1};
            nodes[g].restAndFixed={x,y,z,0};
            nodes[g].velocityAndInverseMass={0.01f*float(i%7u),0,0,1};
            fields[g].primary={0.02f,300.0f+float(i%3u),0,0};
            fields[g].secondary={0.1f,0.2f,0.3f,0.4f};
            residual[g]={1e-7f*float(i%11u),-2e-7f,3e-7f,1e-8f};
            fieldResidual[g]={1e-7f,2e-7f,-3e-7f,4e-7f};
            correction[g]={1e-5f,2e-5f,3e-5f,1e-9f};
            correction[nodes.size()+g]={1e-6f,2e-6f,3e-6f,4e-6f};
        }
        if(fault==2)residual[517].x=1.0f;
        if(fault==3)nodes[1].positionAndMass.x=-1.0f;
        if(fault==4)fieldResidual[517].y=INFINITY;
        std::vector<NMTetrahedronGPU> tets(4);
        for(unsigned env=0;env<2u;++env)for(unsigned o=0;o<2u;++o) {
            auto& t=tets[2u*env+o];t.nodes={4u*o,4u*o+1u,4u*o+2u,4u*o+3u};
            t.identity={0,o,0,NM_OBJECT_ACTIVE};
            t.inverseRestRow0={1,0,0,0};t.inverseRestRow1={0,1,0,0};
            t.inverseRestRow2={0,0,1,0};
        }
        NMMixedMaterialGPU material{};material.mechanics={1000,0,0,300};
        std::vector<NMDeformableContactGPU> contacts(1040);
        std::vector<unsigned> indices(1040,NM_INVALID_INDEX);
        for(unsigned env=0;env<2u;++env)for(unsigned i=0;i<519u;++i) {
            auto& c=contacts[env*520u+i];
            c.identity={0,1,NM_DEFORMABLE_CONTACT_POINT_POINT,NM_CONTACT_VALID};
            c.nodes={0,4,NM_INVALID_INDEX,NM_INVALID_INDEX};
            c.extraNodes={NM_INVALID_INDEX,NM_INVALID_INDEX,0,0};
            c.pointAndSeparation={0,0,0,0.001f};c.barrier.x=float(i%9u);
            c.impulseAndFriction={0,0.02f,0.03f,0};
            indices[env*520u+i]=518u-i;
        }
        if(fault==1)for(unsigned i:{317u,320u})contacts[i].pointAndSeparation.w=0;
        auto zero=makeBuffer(device,std::vector<unsigned>(4096,0));
        auto cb=makeBuffer(device,contacts),counts=makeBuffer(device,std::vector<unsigned>{519,519});
        auto ab=[device newBufferWithLength:ae.encodedLength options:MTLResourceStorageModeShared];
        [ae setArgumentBuffer:ab offset:0];
        for(NSUInteger i=0;i<20u;++i)[ae setBuffer:zero offset:0 atIndex:i];
        [ae setBuffer:cb offset:0 atIndex:7];[ae setBuffer:counts offset:0 atIndex:14];
        std::vector<NMIncidenceRangeGPU> ownerRanges(nodes.size());
        std::vector<unsigned> ownerIncidence;
        for(unsigned env=0;env<2u;++env)for(unsigned node:{0u,4u}) {
            auto& range=ownerRanges[env*d.femNodeCount+node];
            range.first=static_cast<unsigned>(ownerIncidence.size());range.count=519u;
            for(unsigned slot=0;slot<519u;++slot)
                ownerIncidence.push_back(slot*8u+(node==0u?0u:1u));
        }
        const auto ownerRangesBuffer=makeBuffer(device,ownerRanges);
        const auto ownerIncidenceBuffer=makeBuffer(device,ownerIncidence);
        const auto ownerSwitch=makeBuffer(device,std::vector<unsigned>{1u});
        [ae setBuffer:ownerIncidenceBuffer offset:0 atIndex:8];
        [ae setBuffer:ownerRangesBuffer offset:0 atIndex:9];
        NMFGMRESStateGPU st{};st.diagnostics.y=1;
        auto out=makeBuffer(device,std::vector<NMSolverCertificateGPU>(6));
        auto status=makeBuffer(device,std::vector<NMMatterStatusGPU>(2));
        auto telemetry=makeBuffer(device,std::vector<NMFGMRESTelemetryGPU>(2));
        auto nb=makeBuffer(device,nodes),fb=makeBuffer(device,fields);
        std::vector<std::pair<NSUInteger,id<MTLBuffer>>> bindings{
            {0,makeBuffer(device,std::vector<NMMatterDispatchGPU>{d})},
            {1,makeBuffer(device,std::vector<NMMixedSolverGPU>{solver})},
            {2,makeBuffer(device,objects)},{3,nb},{4,nb},{5,fb},{6,fb},
            {7,makeBuffer(device,tets)},{8,out},{9,status},{10,makeBuffer(device,residual)},
            {11,makeBuffer(device,std::vector<NMFGMRESStateGPU>(2,st))},
            {12,makeBuffer(device,fieldResidual)},
            {13,makeBuffer(device,std::vector<NMMixedMaterialGPU>{material})},
            {14,makeBuffer(device,correction)},{15,zero},{16,zero},{17,zero},
            {18,zero},{19,ab},{20,zero},{21,telemetry},{22,makeBuffer(device,indices)},
            {30,makeBuffer(device,std::vector<NMFGMRESLayoutGPU>{layout})}};
        auto execute=[&](bool fast,bool byOwner=false) {
            std::memset(out.contents,0,out.length);std::memset(status.contents,0,status.length);
            std::memset(telemetry.contents,0,telemetry.length);
            auto partial=makeBuffer(device,std::vector<nm_float4>(6u*128u*7u));
            auto command=[queue commandBuffer];auto e=[command computeCommandEncoder];
            for(auto [i,b]:bindings)[e setBuffer:b offset:0 atIndex:i];
            [e useResource:zero usage:MTLResourceUsageRead];
            [e useResource:cb usage:MTLResourceUsageRead];
            [e useResource:counts usage:MTLResourceUsageRead];
            [e useResource:ownerRangesBuffer usage:MTLResourceUsageRead];
            [e useResource:ownerIncidenceBuffer usage:MTLResourceUsageRead];
            [e setBuffer:byOwner?ownerSwitch:zero offset:0 atIndex:24];
            [e setComputePipelineState:fast?tiled:legacy];
            if(fast)[e setBuffer:partial offset:0 atIndex:23];
            [e dispatchThreadgroups:MTLSizeMake(6u*(fast?128u:1u),1,1)
                threadsPerThreadgroup:MTLSizeMake(32,1,1)];
            if(fast) {
                [e memoryBarrierWithScope:MTLBarrierScopeBuffers];
                [e setComputePipelineState:finish];
                [e dispatchThreadgroups:MTLSizeMake(6,1,1)
                    threadsPerThreadgroup:MTLSizeMake(32,1,1)];
            }
            [e endEncoding];[command commit];[command waitUntilCompleted];
            require(command.status==MTLCommandBufferStatusCompleted,"mixed domain GPU execution");
        };
        execute(false);auto ref=readBuffer<NMSolverCertificateGPU>(out,6);
        auto rs=readBuffer<NMMatterStatusGPU>(status,2);
        execute(true);auto actual=readBuffer<NMSolverCertificateGPU>(out,6);
        auto as=readBuffer<NMMatterStatusGPU>(status,2);
        const float* r=reinterpret_cast<const float*>(ref.data());
        const float* a=reinterpret_cast<const float*>(actual.data());
        for(unsigned i=0;i<6u*sizeof(NMSolverCertificateGPU)/sizeof(float);++i)
            require((std::isnan(r[i])&&std::isnan(a[i]))||r[i]==a[i]||
                std::abs(r[i]-a[i])<=1e-8f+1e-5f*std::abs(r[i]),
                "tiled mixed node/field/contact/element certificate parity");
        for(unsigned env=0;env<2;++env) {
            require(rs[env].code==as[env].code,"mixed tiled failure acceptance parity");
            if(fault==1&&env==0)require(as[env].failingIndex==317,
                "mixed tiled deterministic contact witness");
        }
        execute(true,true);
        actual=readBuffer<NMSolverCertificateGPU>(out,6);
        as=readBuffer<NMMatterStatusGPU>(status,2);
        a=reinterpret_cast<const float*>(actual.data());
        for(unsigned i=0;i<6u*sizeof(NMSolverCertificateGPU)/sizeof(float);++i)
            require((std::isnan(r[i])&&std::isnan(a[i]))||r[i]==a[i]||
                std::abs(r[i]-a[i])<=1e-8f+1e-5f*std::abs(r[i]),
                "owner incidence full certificate parity");
        for(unsigned env=0;env<2u;++env) {
            require(rs[env].code==as[env].code,"owner incidence failure acceptance parity");
            if(fault==1&&env==0)require(as[env].failingIndex==317,
                "owner incidence deterministic contact witness");
        }
    }
    std::cout<<"mixed_certificate_tiled domains=FEM_pressure_transport contacts=519 environments=2 objects=3 "
        "faults=clearance_residual_inversion_nonfinite PASS\n";
}

