{{0.000195312707f,0.00095661002f,0.000423580554f,0.0f},{5.127137e-12f,1.69467652e-11f,4.15365528e-12f,0.0f}},
{{2.77868895e-10f,-4.68947825e-10f,1.96981476e-11f,0.0f},{-3.23323726e-18f,-5.13454167e-19f,4.22133634e-19f,0.0f}},
{{-4.00139379e-06f,3.99383316e-06f,-5.42528696e-12f,0.0f},{2.16795224e-15f,-5.92439712e-14f,-1.88298361e-19f,0.0f}},
{{0.000199314803f,0.000956609671f,0.000423580233f,0.0f},{-3.06673111e-12f,-1.98726539e-11f,1.34929715e-11f,0.0f}},
{{0.000195312707f,0.00095661002f,0.000423580554f,0.0f},{5.127137e-12f,1.69467513e-11f,4.15364141e-12f,0.0f}},
{{2.77868867e-10f,-4.68947825e-10f,1.96981459e-11f,0.0f},{-3.89937242e-18f,-5.13454167e-19f,3.80500187e-19f,0.0f}},
{{-4.00139379e-06f,3.99383316e-06f,-5.42528652e-12f,0.0f},{2.16795224e-15f,-5.92723909e-14f,-1.77889999e-19f,0.0f}},
{{0.000199314803f,0.000956609671f,0.000423580233f,0.0f},{-3.06678793e-12f,-1.987264e-11f,1.34929854e-11f,0.0f}},
{{0.000195312707f,0.00095661002f,0.000423580554f,0.0f},{5.12719424e-12f,1.69467374e-11f,4.15362666e-12f,0.0f}}
    };
    const unsigned count = positions.size() / 4u;
    NMDeformableContactGPU contact{};
    contact.identity.z = NM_DEFORMABLE_CONTACT_VERTEX_TRIANGLE;
    contact.barrier.z = 1.0e-5f;
    contact.mollifier.w = 1.0f;
    const auto output = makeBuffer(device, std::vector<nm_float4>(
        count + 4u, {-7.0f,-7.0f,-7.0f,-7.0f}));
    dispatch(device, queue, pipeline(device, library,
        "numi_matter_metal::nm_contact_check_compensated_barrier_words"), {
        {0u,makeBuffer(device,std::vector<NMDeformableContactGPU>(count,contact))},
        {1u,makeBuffer(device,positions)}, {2u,output},
        {3u,makeBuffer(device,std::vector<unsigned>{count})}},
        (count+31u)/32u,32u);
    const auto values=readBuffer<nm_float4>(output,count+4u);
    using V=std::array<double,3u>;
    const auto sub=[](V a,V b){return V{a[0]-b[0],a[1]-b[1],a[2]-b[2]};};
    const auto dot=[](V a,V b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];};
    const auto cross=[](V a,V b){return V{a[1]*b[2]-a[2]*b[1],
        a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};};
    const auto point=[&](unsigned i){auto p=positions[i];return V{
        double(p.high.x)+p.low.x,double(p.high.y)+p.low.y,
        double(p.high.z)+p.low.z};};
    double maxRelative=0.0;
    std::vector<double> expected(count),actual(count);
    for(unsigned i=0u;i<count;++i){
        const auto p=point(4u*i),a=point(4u*i+1u);
        const auto ab=sub(point(4u*i+2u),a),ac=sub(point(4u*i+3u),a);
        const auto ap=sub(p,a),c=cross(ab,ac);
        require(dot(ab,ap)<=0.0 && dot(ac,ap)<=0.0,
            "paired energy reference fixture left its vertex Voronoi region");
        const double r=std::clamp(dot(c,c)/(dot(ab,ab)*dot(ac,ac))/
            double(1.0e-3f),0.0,1.0);
        const double d2=dot(ap,ap),h2=double(contact.barrier.z)*contact.barrier.z;
        expected[i]=r*(2.0-r)*(-(d2-h2)*(d2-h2)*std::log(d2/h2));
        actual[i]=double(values[i].x)+values[i].y;
        require(values[i].w==1.0f,"paired energy rejected a finite native trial");
        maxRelative=std::max(maxRelative,std::abs(actual[i]/expected[i]-1.0));
        require(std::abs(actual[i]/expected[i]-1.0)<=1.0e-9,
            "paired native contact energy differs from Float64 constitutive law");
    }
    for(unsigned i=count;i<count+4u;++i)
        require(values[i].x==-7.0f && values[i].y==-7.0f,
            "paired energy checker exceeded its active span");
    // Comparing small differences is the behavior the scalar output cannot
    // certify. Use pairs from the same current/actual-rounded-trial family.
    unsigned signChecks=0u;
    for(unsigned i=1u;i<count;++i){
        const double referenceDelta=expected[i]-expected[i-1u];
        if(std::abs(referenceDelta)>1.0e-12*expected[i]){
            require((actual[i]>actual[i-1u])==(referenceDelta>0.0),
                "paired energy lost a resolved native trial difference");
            ++signChecks;
        }
    }
    std::cout<<"paired_contact_energy native_trials="<<count
        <<" Float64_max_relative="<<maxRelative<<" sign_checks="<<signChecks
        <<" canaries=4 result=PASS\n";
}

