        require(std::isfinite(fraction) && fraction>=0.0f && fraction<=1.0f,
            "plane certificate returned invalid fraction");
        if (!(fraction>0.0f)) continue;
        ++certified;
        const auto axis=parameters[2u*i];const unsigned kind=unsigned(axis.w);
        const unsigned firstCount=kind==1u?2u:1u,secondBegin=kind==1u?2u:1u;
        const unsigned secondCount=kind==0u?3u:kind==1u?2u:1u;
        const double norm=std::sqrt(double(axis.x)*axis.x+double(axis.y)*axis.y+double(axis.z)*axis.z);
        const double threshold=double(parameters[2u*i+1u].x)*norm;
        const auto projection=[&](unsigned t,unsigned a,unsigned b) {
            const auto p=positions[8u*i+4u*t+a],q=positions[8u*i+4u*t+b];
            return double(axis.x)*((double(p.high.x)+p.low.x)-(double(q.high.x)+q.low.x))+
                double(axis.y)*((double(p.high.y)+p.low.y)-(double(q.high.y)+q.low.y))+
                double(axis.z)*((double(p.high.z)+p.low.z)-(double(q.high.z)+q.low.z));
        };
        for (unsigned a=0u;a<firstCount;++a) for (unsigned b=secondBegin;b<secondBegin+secondCount;++b) {
            const double start=projection(0u,a,b),end=projection(1u,a,b);
            require(start>threshold && (1.0-double(fraction))*start+double(fraction)*end>threshold,
                "outward-rounded plane certificate violated Float64 clearance bound");
        }
    }
    require(certified>=20u,"plane corpus did not exercise enough successful certificates");
    std::cout<<"reference_plane_certificate=true exact_Float32_inputs=true Float64_clearance=true "
        <<"captured_zero_hit_refined=true invalid_rejected=true cases="<<count
        <<" certified="<<certified<<" result=PASS\n";
}


void checkContactArmijoInterpolation(id<MTLDevice> device,id<MTLCommandQueue> queue,id<MTLLibrary> library) {
    const float nan=std::numeric_limits<float>::quiet_NaN();
    std::vector<nm_float4> input;
    for(float curvature:{1.0f,1.0e2f,1.0e4f,1.0e6f})
        for(float scale:{1.0f,1.0e-15f})
            input.push_back({curvature*scale,0.0f,-scale,1.0f});
    input.push_back({nan,0,-1,1});
    input.push_back({1,0,0,1});
    input.push_back({-1,0,-1,1});
    const unsigned count=unsigned(input.size());
    auto out=makeBuffer(device,std::vector<nm_float4>(count+1,{-7,-7,-7,-7}));
    dispatch(device,queue,pipeline(device,library,"numi_matter_metal::nm_contact_armijo_interpolation_check"),{
        {0u,makeBuffer(device,input)},{1u,out},
        {2u,makeBuffer(device,std::vector<unsigned>{count})}},1u,32u);
    const auto result=readBuffer<nm_float4>(out,count+1);
    for(unsigned i=0;i<count;++i) {
        const auto v=input[i];const double delta=double(v.x)+v.y;
        const double linear=double(v.w)*v.z;
        double fraction=0.5;
        if(v.z<0&&std::isfinite(delta)&&linear<0&&std::isfinite(linear)) {
            const double denominator=1-delta/linear;
            if(denominator>0&&std::isfinite(denominator))
                fraction=std::clamp(0.5/denominator,0.1,0.5);
        }
        require(std::isfinite(result[i].x)&&
            std::abs(result[i].x-v.w*fraction)<2.0e-7,"Armijo interpolation Float64 reference");
        require(result[i].x>=0.1f*v.w&&result[i].x<=0.5f*v.w,
            "Armijo proposal escaped safeguarded decreasing interval");
        if(std::isfinite(v.x)&&v.x>0) {
            require(result[i].y>0,"stiff quadratic did not find a certified step in eight evaluations");
            const double alpha=result[i].y;
            const double energyDelta=-alpha+0.5*double(v.x)*alpha*alpha;
            require(energyDelta<=-1.0e-4*alpha+1.0e-12,"quadratic Armijo was bypassed");
        }
    }
    bool dyadicAccepted=false;
    for(unsigned j=0;j<8;++j) {
        const double alpha=std::exp2(-double(j));
        dyadicAccepted=dyadicAccepted||(-alpha+0.5*1.0e6*alpha*alpha<=-1.0e-4*alpha);
    }
    require(!dyadicAccepted,"stiff regression no longer distinguishes fixed dyadic search");
    require(result[count].x==-7&&result[count].y==-7,"Armijo interpolation output canary");
    std::cout<<"contact_armijo_interpolation=true Float64_reference=true fixed_evaluation_budget=8 stiff_quadratic=true invalid_data_halving=true canary=true cases="<<count<<" PASS\n";
}

void checkFEMAlignedBarrier(id<MTLDevice> device,id<MTLCommandQueue> queue,id<MTLLibrary> library) {
    std::vector<nm_float4> input,parameters;
    for(float width:{2.0e-9f,2.0e-5f,0.02f})for(float fraction:{1.0e-6f,5.0e-5f,2.0e-4f,0.01f,0.1f,0.4f,0.8f,0.99f,1.0f,1.2f}) {
        const float offset=0.5f*width;
        input.push_back({offset+fraction*(width-offset),width,offset,0.0f});
        parameters.push_back({7.4e10f,1.5625e-5f,0.0f,0.0f});
    }
    // Independent coefficient checks include cases where the old dimensional
    // 1e-20 denominator floor silently weakened the intended inertial barrier.
    // Also exercise the closing-speed branch; Float64 reference does not read
    // the GPU-reported coefficient.
    for(float width:{2.0e-9f,2.0e-5f,0.02f})
        for(float inverseResponse:{1.0e2f,1.0e5f,7.4e10f})
            for(float dt:{1.5625e-5f,1.25e-4f,2.0e-3f})
                for(float impactRatio:{0.0f,0.5f,2.0f}) {
                    const float offset=0.5f*width,w=width-offset;
                    const float separation=offset+0.4f*w;
                    const float remaining=width-separation;
                    input.push_back({separation,width,offset,0.0f});
                    parameters.push_back({inverseResponse,dt,
                        impactRatio*10.0f*remaining/dt,0.0f});
                }
    // Paired distances whose positive gap is lost or distorted by projecting
    // the distance before subtracting clearance, including the native141 scale.
    for(float low:{2.0e-17f,5.0e-17f,7.0e-16f,1.0e-19f}) {
        input.push_back({1.0e-9f,2.0e-9f,1.0e-9f,low});
        parameters.push_back({6.76168e12f,1.5625e-5f,0.0f,0.0f});
    }
    const unsigned validCount=unsigned(input.size());
    for(unsigned mode=0;mode<4;++mode) {
        input.push_back({mode==0?1.0e-9f:mode==1?0.5e-9f:1.5e-9f,2.0e-9f,
            mode==2?-1.0e-9f:mode==3?2.0e-9f:1.0e-9f,0.0f});
        parameters.push_back({7.4e10f,1.5625e-5f,0,0});
    }
    const unsigned count=unsigned(input.size());
    auto output=makeBuffer(device,std::vector<nm_float4>(count+1,{-7,-7,-7,-7}));
    auto metadata=makeBuffer(device,std::vector<nm_float4>(count+1,{-7,-7,-7,-7}));
    dispatch(device,queue,pipeline(device,library,"numi_matter_metal::nm_contact_fem_aligned_barrier_check"),{
        {0u,makeBuffer(device,input)},{1u,makeBuffer(device,parameters)},{2u,output},
        {3u,metadata},{4u,makeBuffer(device,std::vector<unsigned>{count})}},(count+31)/32,32u);
    auto got=readBuffer<nm_float4>(output,count+1),meta=readBuffer<nm_float4>(metadata,count+1);
    auto close=[](double a,double b,double tolerance) {
        return std::isfinite(a)&&std::isfinite(b)&&std::abs(a-b)<=tolerance*std::max(std::abs(b),1.0e-300);
    };
    for(unsigned i=0;i<validCount;++i) {
        const auto a=input[i],p=parameters[i];
        const double gap=(double(a.x)-a.z)+a.w,w=double(a.y)-a.z,dt=p.y;
        require(meta[i].x==a.y,"aligned barrier changed activation metadata");
        if(gap>=w) {
            require(got[i].x==0&&got[i].y==0&&got[i].z==0&&got[i].w==0,
                "aligned barrier must deactivate at unchanged world activation");continue;
        }
        require(std::isfinite(meta[i].y)&&meta[i].y>0,"aligned stiffness finite");
        const double d=gap,s=d*d-w*w;
        const double expectedScale=std::max(10.0/(double(p.x)*dt*dt),
            std::max(double(p.z),0.0)/(double(p.x)*dt*std::max(w-d,1.0e-3*w)));
        const double expectedK=expectedScale/(w*w);
        require(close(meta[i].y,expectedK,5.0e-6),
            "aligned stiffness violates independent inertial/impact scaling");
        const double k=meta[i].y;
        const double l=std::log((d*d)/(w*w));
        const double first=-k*(2*s*l+s*s/(d*d));
        const double second=-k*(2*l+4*s/(d*d)-s*s/(d*d*d*d));
        const double e0=-k*s*s*l;
        const double energy=e0;
        const double impulse=-2*d*first*dt;
        const double curvature=std::max(4*d*d*second+2*first,0.0)*dt*dt;
        const double gpuEnergy=double(got[i].x)+got[i].y;
        require(close(gpuEnergy,energy,5.0e-4),"shifted paired potential differs from Float64 IPC");
        require(close(got[i].z,impulse,5.0e-4),"shifted force is not potential derivative");
        require(curvature==0?got[i].w==0:close(got[i].w,curvature,7.0e-4),
            "shifted curvature differs from potential Hessian");
        require(close(meta[i].z,energy,8.0e-4),"shifted scalar and paired potential disagree");
        // Independent finite difference of the same potential with frozen k.
        if(gap>0.0&&gap<0.9*w) {
            const auto energyAt=[&](double x) {const double s0=x*x-w*w;return -k*s0*s0*std::log(x*x/(w*w));};
            const double h=std::min(gap,w-gap)*1.0e-4;
            const double derivative=(energyAt(gap+h)-energyAt(gap-h))/(2*h);
            require(close(got[i].z,-derivative*dt,8.0e-4),"aligned finite-difference force");
        }
    }
    for(unsigned i=validCount;i<count;++i)
        require(!std::isfinite(got[i].x)&&!std::isfinite(got[i].z),"invalid shifted domain accepted");
    std::vector<NMDeformableContactGPU> contacts(count);
    for(unsigned i=0;i<count;++i) {
        contacts[i].pointAndSeparation.w=input[i].x;
        contacts[i].barrier.z=input[i].y;contacts[i].barrier.w=meta[i].y*0.25f;
        contacts[i].barrierHessianRow2.w=input[i].z;
        if(input[i].w!=0.0f)contacts[i].barrierHessianRow0.w=
            float((double(input[i].x)-input[i].z)+input[i].w);
    }
    auto certificateEnergy=makeBuffer(device,std::vector<float>(count+1,-7.0f));
    dispatch(device,queue,pipeline(device,library,
        "numi_matter_metal::nm_mixed_contact_energy_check",false,true),{
        {0u,makeBuffer(device,contacts)},{1u,certificateEnergy},
        {2u,makeBuffer(device,std::vector<unsigned>{count})}},(count+31)/32,32u);
    const auto reported=readBuffer<float>(certificateEnergy,count+1);
    for(unsigned i=0;i<count;++i) {
        if(i>=validCount)require(!std::isfinite(reported[i]),"certificate accepted invalid shifted contact");
        else if(got[i].x==0.0f)require(reported[i]==0.0f,"certificate activation differs from potential");
        else require(close(reported[i],(double(got[i].x)+got[i].y)*0.25,8.0e-4),
            "certificate contact energy differs from assembled potential");
    }
    require(reported[count]==-7.0f,"certificate energy output canary");
    require(got[count].x==-7&&meta[count].w==-7,"aligned barrier output canary");
    std::cout<<"fem_clearance_aligned_barrier=true Float64_energy_force_curvature=true "
        "nanometre_underflow_avoided=true positive_gap_no_flat_curvature=true paired_response_and_certificate=true independent_inertial_impact_scaling=true invalid_domain_rejected=true cases="<<count<<" PASS\n";
}



void checkCompactImmutableHumanContactRows(id<MTLDevice> device,
    id<MTLCommandQueue> queue,id<MTLLibrary> library) {
    using namespace numi::matter::detail;
    CompactHumanContactRows packed;
    require(!packCompactHumanContactRows({}, {}, packed),"empty compact contact source accepted");
    constexpr std::uint32_t count=1027u;
    std::vector<NMNumiHumanFEMBodyContactSampleGPU> samples(count);
    std::vector<NMNumiHumanFEMBodyContactNeighborhoodRangeGPU> ranges(count);
    for(std::uint32_t i=0u;i<count;++i) {
        std::array<std::uint32_t,16> words{};
        const auto node=(i/7u)%13u,body=i%7u;
        words[0]=node;words[1]=body;words[2]=3u;words[3]=0u;
        for(std::uint32_t k=4u;k<16u;++k)
            words[k]=0x3f800000u+((k%4u==3u)?node:body)*64u+k;
        // Preserve signed zero too, without normalizing source fields.
        if(node==0u)words[15]=0x80000000u;
        std::memcpy(&samples[i],words.data(),64u);
        std::array<std::uint32_t,8> rw{body*11u,11u,0x3c23d70au,3u,0u,0u,0u,0u};
        std::memcpy(&ranges[i],rw.data(),32u);
    }
    require(!packCompactHumanContactRows(samples,
        std::span<const NMNumiHumanFEMBodyContactNeighborhoodRangeGPU>(ranges).first(1u),packed),
        "mismatched compact contact source accepted");
    require(packCompactHumanContactRows(samples,ranges,packed),"compact contact pack failed");
    require(packed.rows==count&&packed.templates==13u&&packed.seeds==7u,
        "contact template/seed ownership differs");
    require(packed.bytes.size()<samples.size()*96u,"contact fixture did not reduce storage");
    for(std::uint32_t i=0;i<count;++i) {
        NMNumiHumanFEMBodyContactSampleGPU sample{};
        NMNumiHumanFEMBodyContactNeighborhoodRangeGPU range{};
        require(decodeCompactHumanContactRow(packed.bytes,i,sample,range),
            "valid compact contact row rejected");
        require(std::memcmp(&sample,&samples[i],64u)==0&&
            std::memcmp(&range,&ranges[i],32u)==0,"CPU contact reconstruction changed bits");
    }
    NMNumiHumanFEMBodyContactSampleGPU sample{};
    NMNumiHumanFEMBodyContactNeighborhoodRangeGPU range{};
    require(!decodeCompactHumanContactRow(packed.bytes,count,sample,range),
        "out-of-range compact contact row accepted");
    const auto verify=pipeline(device,library,
        "numi_matter_metal::nm_numi_human_verify_compact_contact_rows");
    const auto sampleBuffer=makeBuffer(device,samples), rangeBuffer=makeBuffer(device,ranges);
    const auto countBuffer=makeBuffer(device,std::vector<std::uint32_t>{count});
    const auto failures=makeBuffer(device,std::vector<std::uint32_t>(count,0xffffffffu));
    const auto run=[&](const std::vector<std::byte>& storage,bool bad) {
        const auto buffer=makeBuffer(device,storage);
        dispatch(device,queue,verify,{{0u,buffer},{1u,sampleBuffer},{2u,rangeBuffer},
            {3u,failures},{4u,countBuffer}},(count+31u)/32u,32u);
        const auto result=readBuffer<std::uint32_t>(failures,count);
        for(std::uint32_t i=0;i<count;++i)
            require(bad?(i==0u?result[i]!=0u:result[i]==0u):result[i]==0u,
                "GPU compact contact reconstruction/invalid-index isolation failed");
    };
    run(packed.bytes,false);
    auto corrupt=packed.bytes;
    const std::uint32_t invalid=0xffffffffu;
    std::memcpy(corrupt.data()+32u,&invalid,4u);
    require(!decodeCompactHumanContactRow(corrupt,0u,sample,range),
        "invalid template lookup accepted");
    run(corrupt,true);
    corrupt=packed.bytes;
    std::memcpy(corrupt.data()+20u,&invalid,4u);
    require(!decodeCompactHumanContactRow(corrupt,0u,sample,range),
        "overflowed compact table offset accepted");
}


void checkCooperativeTangentDispatch(
    id<MTLDevice> device,id<MTLCommandQueue> queue,id<MTLLibrary> library) {
    const auto prepare=pipeline(device,library,
        "numi_matter_metal::nm_fem_prepare_cooperative_tangent_dispatch");
    const std::vector<std::uint32_t> groups{0u,1u,185000u,0xffffffffu};
    const auto counts=makeBuffer(device,groups);
    const auto count=makeBuffer(device,std::vector<std::uint32_t>{4u});
    for (std::uint32_t environments:{1u,2u})
    for (std::uint32_t iteration:{0u,1u,15u})
    for (bool completed:{false,true})
    for (bool healthy:{false,true})
    for (std::uint32_t force:{0u,1u}) {
        NMMatterDispatchGPU domain{};domain.environmentCount=environments;
        NMMicrostepGPU micro{};micro.solverIteration=iteration;
        NMFGMRESStateGPU state{};state.nonlinear.w=completed?1.0f:0.0f;
        NMMatterStatusGPU status{};
        if(!healthy) status.code=NM_STATUS_NONFINITE_RESULT;
        const auto domainBuffer=makeBuffer(device,std::vector<NMMatterDispatchGPU>{domain});
        const auto microBuffer=makeBuffer(device,std::vector<NMMicrostepGPU>{micro});
        const auto states=makeBuffer(device,std::vector<NMFGMRESStateGPU>{state,state});
        const auto statuses=makeBuffer(device,std::vector<NMMatterStatusGPU>{status,status});
        const auto rebuild=makeBuffer(device,std::vector<std::uint32_t>{force});
        NMIndirectDispatchGPU sentinel{77u,88u,99u,111u};
        const auto arguments=makeBuffer(device,std::vector<NMIndirectDispatchGPU>(5u,sentinel));
        dispatch(device,queue,prepare,
            {{0u,domainBuffer},{1u,microBuffer},{2u,states},{3u,statuses},
             {4u,counts},{5u,count},{6u,rebuild},{7u,arguments}},1u,32u);
        const auto out=readBuffer<NMIndirectDispatchGPU>(arguments,5u);
        const bool skip=environments==1u&&iteration>0u&&completed&&healthy&&force==0u;
        for(std::size_t i=0;i<groups.size();++i) {
            NMIndirectDispatchGPU expected{skip?0u:groups[i],1u,1u,0u};
            require(std::memcmp(&out[i],&expected,sizeof(expected))==0,
                "cooperative tangent dispatch changed subset or tail policy");
        }
        require(std::memcmp(&out[4],&sentinel,sizeof(sentinel))==0,
            "cooperative tangent dispatch exceeded argument capacity");
    }
}

int main(int argc, const char* argv[]) {
    @autoreleasepool {
        try {
            id<MTLDevice> device = MTLCreateSystemDefaultDevice();
            require(device != nil, "Metal device unavailable");
            id<MTLCommandQueue> queue = [device newCommandQueue];
            require(queue != nil, "Metal command queue unavailable");

            NSError* error = nil;
            NSURL* libraryURL = [NSURL fileURLWithPath:
                [NSString stringWithUTF8String:NUMI_MATTER_METALLIB]];
            id<MTLLibrary> library =
                [device newLibraryWithURL:libraryURL error:&error];
            require(library != nil, error != nil
                ? std::string("cannot load Matter metallib: ") +
                    [[error localizedDescription] UTF8String]
                : "cannot load Matter metallib");
            if(argc==2&&std::string(argv[1])=="--accepted-subspace-only") {
                checkAcceptedSubspacePredictor(device,queue,library);
                checkAcceptedSubspaceAdmission(device,queue,library);
                std::cout<<"PASS accepted subspace "<<checks<<" checks\n";
                return 0;
            }
            if(argc==2&&std::string(argv[1])=="--cooperative-tangent-dispatch-only") {
                checkCooperativeTangentDispatch(device,queue,library);
                std::cout<<"PASS cooperative tangent dispatch "<<checks<<" checks\n";
                return 0;
            }
            if(argc==2&&std::string(argv[1])=="--reference-surface-only") {
                checkReferenceSurfaceGeometry(device,queue,library);
                checkPolynomialReferenceSweep(device,queue,library);
                checkPolynomialPrefixSweep(device,queue,library);
                checkPolynomialSweepControls(device,queue,library);return 0;
            }
            if(argc==2&&std::string(argv[1])=="--reference-rest-margin-only") {
                checkCapturedInitialNonclosing(device,queue,library);
                checkCapturedRestMarginSweep(device,queue,library);
                checkFinalReferenceContactClearance(device,queue,library);
                std::cout<<"PASS reference rest margin "<<checks<<" checks\n";
                return 0;
            }
            if(argc==2&&std::string(argv[1])=="--unresolved-reference-sweep-only") {
                checkReferenceEndpointPotential(device,queue,library);
                checkUnresolvedReferenceSweepProof(device,queue,library);return 0;
            }
            if(argc==2&&std::string(argv[1])=="--tiled-mixed-certificate-only") {
                checkFinalContactActivePrefix(device,queue,library);
                checkTiledMixedCertificateDomains(device,queue,library);
                std::cout<<"PASS tiled mixed certificate "<<checks<<" checks\n";
                return 0;
            }
            if(argc==2&&std::string(argv[1])=="--contact-armijo-interpolation-only") {
                checkContactArmijoInterpolation(device,queue,library);return 0;
            }
            if(argc==2&&std::string(argv[1])=="--fem-aligned-barrier-only") {
                checkFEMAlignedBarrier(device,queue,library);return 0;
            }
            if(argc==2&&std::string(argv[1])=="--thin-contact-energy-only") {
                checkThinContactEnergy(device,queue,library);return 0;
            }
            if (argc==2 && std::string(argv[1])=="--reference-plane-only") {
                checkReferenceContactPlaneCertificate(device,queue,library);
                std::cout<<"PASS reference contact plane "<<checks<<" checks\n";
                return 0;
            }
            if (argc == 2 && std::string(argv[1]) == "--reference-self-contact-width-only") {
                checkReferenceSelfContactWidth(device,queue,library);return 0;
            }
            if (argc == 2 && std::string(argv[1]) == "--resolved-mollifier-curvature-only") {
                checkResolvedMollifierCurvature(device,queue,library);
                return 0;
            }
            if (argc == 2 && std::string(argv[1]) == "--paired-contact-energy-only") {
                checkCompensatedBarrierEnergyWords(device,queue,library);
                return 0;
            }
            if (argc == 2 && std::string(argv[1]) == "--compensated-contact-continuity-only") {
                checkCompensatedContactEnergyContinuity(device,queue,library);
                std::cout << "PASS compensated contact continuity " << checks << " checks\n";
                return 0;
            }
            if (argc == 2 && std::string(argv[1]) ==
                    "--reference-contact-frame-only") {
                checkReferenceContactArithmeticFrame(device, queue, library);
                std::cout << "PASS native reference contact frame " << checks << " checks\n";
                return 0;
            }
            if (argc == 2 && std::string(argv[1]) ==
                    "--inexact-coupled-certificate-only") {
                checkInexactCoupledLinearCertificate(device, queue, library);
                auto p = [&](const char* name) { return pipeline(device, library, name); };
                auto q = [&](const char* name) { return pipelineWithRelativeInnerForcingDisabled(device, library, name); };
                checkDistributedBeginAndCorrection(device, queue, library,
                    q("numi_matter_metal::nm_fgmres_begin"),
                    p("numi_matter_metal::nm_fgmres_begin_distributed_partial"),
                    q("numi_matter_metal::nm_fgmres_begin_distributed_finish"),
                    q("numi_matter_metal::nm_fgmres_begin_distributed_basis0"),
                    p("numi_matter_metal::nm_fgmres_measure_correction"),
                    p("numi_matter_metal::nm_fgmres_correction_distributed_partial"),
                    p("numi_matter_metal::nm_fgmres_correction_distributed_finish"),
                    p("numi_matter_metal::nm_fgmres_true_residual_distributed_partial"),
                    q("numi_matter_metal::nm_fgmres_true_residual_distributed_finish"), true);
                checkInexactNewtonForcing(device, queue,
                    p("numi_matter_metal::nm_fgmres_prepare_inexact_newton_forcing"),
                    p("numi_matter_metal::nm_fgmres_commit_inexact_newton_history"));
                std::cout << "PASS inexact coupled certificate " << checks << " checks\n";
                return 0;
            }
            if (argc == 2 && std::string(argv[1]) ==
                    "--fresh-direction-common-alpha-reset-only") {
                checkFreshDirectionCommonAlphaReset(device, queue, library);
                std::cout << "PASS fresh direction common-alpha reset "
                          << checks << " checks" << std::endl;
                return 0;
            }
            if (argc == 2 && std::string(argv[1]) == "--aggregate-cycle-icb-range-only") {
                checkAggregateCycleICBRange(device, queue, library);
                std::cout << "PASS aggregate-cycle ICB range " << checks << " checks" << std::endl;
                return 0;
            }
            if (argc == 2 && std::string(argv[1]) == "--fresh-rhs-preconditioner-begin-verify-only") {
                checkFreshRhsPreconditionerBeginVerification(device, queue, library);
                std::cout << "PASS fresh-RHS preconditioner begin verification "
                          << checks << " checks" << std::endl;
                return 0;
            }
            if (argc == 2 && std::string(argv[1]) == "--fresh-rhs-preconditioner-ranges-only") {
                checkFreshRhsPreconditionerRanges(device, queue, library);
                std::cout << "PASS fresh-RHS preconditioner ranges "
                          << checks << " checks" << std::endl;
                return 0;
            }
